/* @socom-skeleton stub CalcDrawPos__11CZNewHudMapCFf */
float CZNewHudMap::CalcDrawPos(float y) const
{
	/* 0x3c56c0 */
	return m_screencentery + m_scale * (y - m_screencentery);
}

